   120|// POST /api/members/register
   121|// Phase 2 reliability: accepts `registrationRequestId` for idempotency + resume.
   122|// Returns the normalized { ok, code, message, traceId, stage, retryable, ... } contract.
   123|export async function handleMemberRegister(request: Request): Promise<Response> {
   124|  const body = await parseBody(request);
   125|  const email = asString(body.email).toLowerCase();
   126|  const password = asString(body.password);
   127|  const firstName = asString(body.firstName);
   128|  const lastName = asString(body.lastName);
   129|  const phone = asString(body.phone);
   130|  const country = asString(body.country);
   131|  const zipCode = asString(body.zipCode);
   132|  const roles: MemberRoleInterest[] = Array.isArray(body.roles)
   133|    ? (body.roles.filter(
   134|        (r): r is MemberRoleInterest => typeof r === 'string' && VALID_ROLE_INTERESTS.has(r as MemberRoleInterest)
   135|      ))
   136|    : [];
   137|  const acceptTerms = !!body.acceptTerms;
   138|  const pictureUrl = asString(body.pictureUrl);
   139|  const dateOfBirth = asString(body.dateOfBirth);
   140|  const gender = asString(body.gender).toLowerCase();
   141|  const registrationRequestId = asString(body.registrationRequestId) || undefined;
   142|  const opportunityId = asString(body.opportunityId) || undefined;
   143|  const opportunityTitle = asString(body.opportunityTitle) || undefined;
   144|  const amount = typeof body.amount === 'number' ? body.amount : undefined;
   145|  const investmentType = asString(body.investmentType) || undefined;
   146|
   147|  // Validation — returns the normalized error contract (no raw strings).
   148|  // These are pre-orchestrator checks that never touch the network.
   149|  if (!firstName || !lastName) {
   150|    return normalizedError('INVALID_EMAIL', 'VALIDATING', { message: 'First name and last name are required.' });
   151|  }
   152|  if (!isValidEmail(email)) {
   153|    return normalizedError('INVALID_EMAIL', 'VALIDATING', { message: 'Please enter a valid email address.' });
   154|  }
   155|  const pwCheck = validatePassword(password);
   156|  if (!pwCheck.valid) {
   157|    return normalizedError('WEAK_PASSWORD', 'VALIDATING', { message: pwCheck.reason || 'Password does not meet requirements.' });
   158|  }
   159|  if (!phone || phone.replace(/\D/g, '').length < 10) {
   160|    return normalizedError('INVALID_EMAIL', 'VALIDATING', { message: 'Please enter a valid phone number.' });
   161|  }
   162|  if (!acceptTerms) {
   163|    return normalizedError('UNKNOWN_ERROR', 'VALIDATING', { message: 'You must accept the Terms of Service.' });
   164|  }
   165|  const dobCheck = validateDateOfBirth(dateOfBirth);
   166|  if (!dobCheck.valid) {
   167|    return normalizedError('INVALID_EMAIL', 'VALIDATING', { message: dobCheck.reason || 'Please enter a valid date of birth.' });
   168|  }
   169|  const genderCheck = validateGender(gender);
   170|  if (!genderCheck.valid) {
   171|    return normalizedError('INVALID_EMAIL', 'VALIDATING', { message: genderCheck.reason || 'Gender is required.' });
   172|  }
   173|  if (roles.length === 0) {
   174|    return normalizedError('UNKNOWN_ERROR', 'VALIDATING', { message: 'Please select at least one role to continue.' });
   175|  }
   176|
   177|  // Delegate to the idempotent orchestrator (Auth + profile + fanout + persistence).
   178|  const input: RegistrationRequestInput = {
   179|    email,
   180|    password,
   181|    firstName,
   182|    lastName,
   183|    dateOfBirth,
   184|    gender,
   185|    phone,
   186|    country,
   187|    zipCode,
   188|    roles,
   189|    acceptTerms,
   190|    pictureUrl,
   191|    registrationRequestId,
   192|    opportunityId,
   193|    opportunityTitle,
   194|    amount,
   195|    investmentType,
   196|  };
   197|  const result = await orchestrateRegistration(input);
   198|  return normalizedResponse(result);
   199|}
