    72|async function insertRoleSpecificRecords(input: {
    73|  authUserId: string;
    74|  email: string;
    75|  roles: MemberRoleInterest[];
    76|  registrationRequestId: string;
    77|}): Promise<{ ok: boolean; errors: string[] }> {
    78|  const errors: string[] = [];
    79|  const supabase = getSupabaseAdmin();
    80|
    81|  for (const role of input.roles) {
    82|    const tableName = ROLE_TABLE_MAP[role];
    83|    if (!tableName) continue; // Skip 'jv_deals' and unknown roles
    84|
    85|    try {
    86|      const row = buildRoleRow(role, tableName, input.authUserId, input.email);
    87|      const conflictCol = getConflictColumn(tableName);
    88|      // Use insert for investors table — PostgREST schema cache may not recognize
    89|      // the new unique index on user_id. New registrations always create new auth
    90|      // users, so insert is safe (no conflict expected).
    91|      const useInsert = tableName === 'investors';
    92|      const { error } = useInsert
    93|        ? await supabase.from(tableName).insert(row)
    94|        : await supabase.from(tableName).upsert(row, { onConflict: conflictCol });
    95|
    96|      if (error) {
    97|        console.error(`[RegistrationOrchestrator] ${tableName} ${useInsert ? 'insert' : 'upsert'} failed:`, error.message);
    98|        errors.push(`${role}:${error.message}`);
    99|      }
